import * as Schema29 from "effect-v011/Schema";
var DesktopBackendBootstrap = Schema29.Struct({
  mode: Schema29.Literal("desktop"),
  noBrowser: Schema29.Boolean,
  port: PortSchema,
  // Omitted when the desktop launches the backend inside WSL, since the
  // Windows-side baseDir maps to /mnt/c/... and the Linux side should use its
  // own home directory instead.
  t3Home: Schema29.optional(Schema29.String),
  host: Schema29.String,
  desktopBootstrapToken: Schema29.String,
  // Present when the desktop rotates the renderer's bootstrap token: the
  // backend derives the accepted tokens from this secret instead of trusting
  // `desktopBootstrapToken` for its whole run. See
  // `@t3tools/shared/desktopBootstrapToken`.
  desktopBootstrapSecret: Schema29.optionalKey(Schema29.String),
  // Set only when the desktop already merged the user's shell environment into
  // the environment it hands this backend. Absent means the backend hydrates
  // PATH itself, which WSL and older desktops rely on.
  shellEnvironmentPrepared: Schema29.optionalKey(Schema29.Boolean),
  tailscaleServeEnabled: Schema29.Boolean,
  tailscaleServePort: PortSchema,
  otlpTracesUrl: Schema29.optional(Schema29.String),
  otlpMetricsUrl: Schema29.optional(Schema29.String),
  otlpLogsUrl: Schema29.optional(Schema29.String),
  desktopTelemetryFd: Schema29.optionalKey(PositiveInt),
  desktopTelemetryControlFd: Schema29.optionalKey(PositiveInt),
  desktopBrowserFd: Schema29.optionalKey(PositiveInt),
  desktopBrowserControlFd: Schema29.optionalKey(PositiveInt),
  resourceMonitorPath: Schema29.optionalKey(TrimmedNonEmptyString)
});

