// t3code-v0.1.1/packages/contracts/src/usage.ts
import * as Schema64 from "effect-v011/Schema";
var UsageProviderKind = Schema64.Literals([
  "claude",
  "codex",
  "grok",
  "cursor",
  "opencode",
  "antigravity",
  "pi"
]);
var USAGE_DAY_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
var UsageDay = TrimmedNonEmptyString.check(Schema64.isPattern(USAGE_DAY_PATTERN)).pipe(
  Schema64.brand("UsageDay")
);
var UsageResolution = Schema64.Literals(["day", "hour"]);
var UsageCostSource = Schema64.Literals(["providerReported", "modelPriced", "unpriced"]);
var UsageTokenTotals = Schema64.Struct({
  uncachedInputTokens: NonNegativeInt,
  cachedInputTokens: NonNegativeInt,
  cacheCreationTokens: NonNegativeInt,
  outputTokens: NonNegativeInt,
  reasoningTokens: NonNegativeInt
});
var UsageCategoryCost = Schema64.Struct({
  input: Schema64.Number,
  cacheRead: Schema64.Number,
  cacheWrite: Schema64.Number,
  output: Schema64.Number
});
var UsageBucket = Schema64.Struct({
  day: UsageDay,
  hourStart: Schema64.optional(TrimmedNonEmptyString),
  provider: UsageProviderKind,
  model: TrimmedNonEmptyString,
  sourcePath: Schema64.optional(TrimmedNonEmptyString),
  totals: UsageTokenTotals,
  costUsd: Schema64.Number,
  cacheSavingsUsd: Schema64.Number,
  categoryCostUsd: Schema64.optional(UsageCategoryCost),
  fastCostUsd: Schema64.optional(Schema64.Number),
  ultrafastCostUsd: Schema64.optional(Schema64.Number),
  speedPremiumUsd: Schema64.optional(Schema64.Number),
  costSource: UsageCostSource,
  records: NonNegativeInt,
  unpricedRecords: NonNegativeInt,
  sessions: NonNegativeInt
});
var UsageSourceFingerprint = Schema64.Struct({
  hostId: TrimmedNonEmptyString,
  provider: UsageProviderKind,
  resolvedHomePath: TrimmedNonEmptyString,
  /**
   * Filesystem identity of the transcript directory, as `device:inode`.
   * Hostname and path alone are not enough: every Mac in a fleet resolves
   * `/Users/<user>/.claude`, so two machines that happen to share a hostname
   * would look like one source and have their usage silently dropped.
   */
  volumeId: Schema64.String
});
var UsageSourceStatus = Schema64.Literals(["ok", "missing", "partial", "failed"]);
var UsageSource = Schema64.Struct({
  fingerprint: UsageSourceFingerprint,
  status: UsageSourceStatus,
  scannedFiles: NonNegativeInt,
  skippedFiles: NonNegativeInt,
  malformedRecords: NonNegativeInt,
  /**
   * Buckets also carry per-bucket session counts, but a session spans days and
   * models, so summing those overcounts; this is the figure clients should
   * total.
   */
  distinctSessions: NonNegativeInt,
  message: Schema64.NullOr(TrimmedNonEmptyString),
  action: Schema64.optionalKey(Schema64.Literal("enableCursorKeychain")),
  /**
   * Present when this source answered from its cache while a slow refresh (an
   * account API, for example) runs. Repeat the request with `awaitRefresh` to
   * get the refreshed source.
   */
  refreshing: Schema64.optionalKey(Schema64.Literal(true))
});
var UsagePricingStatus = Schema64.Literals(["fresh", "cached", "unavailable"]);
var UsagePricing = Schema64.Struct({
  status: UsagePricingStatus,
  source: TrimmedNonEmptyString,
  fetchedAt: Schema64.NullOr(Schema64.String),
  knownModels: NonNegativeInt
});
var UsageSummaryInput = Schema64.Struct({
  sinceDay: UsageDay,
  untilDay: UsageDay,
  /**
   * IANA zone the client wants days bucketed in. An offset would be wrong for
   * any window that crosses a DST boundary.
   */
  timeZone: TrimmedNonEmptyString,
  resolution: Schema64.optional(UsageResolution),
  sinceTime: Schema64.optional(TrimmedNonEmptyString),
  untilTime: Schema64.optional(TrimmedNonEmptyString),
  awaitRefresh: Schema64.optional(Schema64.Boolean)
});
var UsageSummary = Schema64.Struct({
  contractVersion: Schema64.Number,
  readAt: Schema64.String,
  timeZone: TrimmedNonEmptyString,
  sinceDay: UsageDay,
  untilDay: UsageDay,
  buckets: ForwardCompatibleArray(UsageBucket),
  sources: ForwardCompatibleArray(UsageSource),
  pricing: UsagePricing,
  scanDurationMs: NonNegativeInt
});
var UsageReadError = class extends Schema64.TaggedError()("UsageReadError", {
  reason: Schema64.Literals(["scanFailed", "invalidWindow"]),
  detail: TrimmedNonEmptyString,
  cause: Schema64.optional(Schema64.Defect())
}) {
  get message() {
    return `Usage read failed (${this.reason}): ${this.detail}`;
  }
};

// t3code-v0.1.1/packages/contracts/src/worktreeMcp.ts
import * as Schema65 from "effect-v011/Schema";
var WorktreeMcpHandoffInput = Schema65.Struct({
  branch: TrimmedNonEmptyString.annotate({
    description: "Branch name to create for the worktree (e.g. 'feature/my-change')."
  }),
  baseRef: Schema65.optional(
    TrimmedNonEmptyString.annotate({
      description: "Branch or ref the worktree branch starts from. Defaults to the branch currently checked out in the project workspace."
    })
  ),
  startFromOrigin: Schema65.optional(
    Schema65.Boolean.annotate({
      description: "Fetch the remote baseRef belongs to and start the worktree branch from its remote-tracking commit instead of the local ref. Defaults to the server's 'new worktrees start from remote' setting."
    })
  ),
  runSetupScript: Schema65.optional(
    Schema65.Boolean.annotate({
      description: "Run the project's configured setup script in the new worktree after handoff. Defaults to true."
    })
  ),
  continuationPrompt: Schema65.optional(
    TrimmedNonEmptyString.check(Schema65.isMaxLength(12e4)).annotate({
      description: "Message queued as the thread's next turn after the handoff. The handoff detaches the current provider session, so pass the remaining work here to automatically resume inside the worktree; omit it to stop after the handoff and wait for the next message."
    })
  )
});
var WorktreeMcpSetupScriptStatus = Schema65.Union([
  Schema65.Struct({
    status: Schema65.Literal("started"),
    scriptName: TrimmedNonEmptyString,
    terminalId: TrimmedNonEmptyString
  }),
  Schema65.Struct({
    status: Schema65.Literal("no-script")
  }),
  Schema65.Struct({
    status: Schema65.Literal("skipped")
  }),
  Schema65.Struct({
    status: Schema65.Literal("failed"),
    detail: Schema65.String
  })
]);
var WorktreeMcpContinuationStatus = Schema65.Union([
  Schema65.Struct({
    status: Schema65.Literal("scheduled"),
    delivery: Schema65.Literals(["started", "queued", "steered", "restarted"])
  }),
  Schema65.Struct({
    status: Schema65.Literal("skipped")
  }),
  Schema65.Struct({
    status: Schema65.Literal("failed"),
    detail: Schema65.String
  })
]);
var WorktreeMcpHandoffResult = Schema65.Struct({
  worktreePath: TrimmedNonEmptyString,
  branch: TrimmedNonEmptyString,
  baseRef: TrimmedNonEmptyString,
  startedFromOrigin: Schema65.Boolean,
  setupScript: WorktreeMcpSetupScriptStatus,
  continuation: WorktreeMcpContinuationStatus,
  note: Schema65.String
});
var WorktreeMcpStatusResult = Schema65.Struct({
  attached: Schema65.Boolean.annotate({
    description: "True when this thread is already attached to a git worktree."
  }),
  worktreePath: Schema65.NullOr(TrimmedNonEmptyString),
  branch: Schema65.NullOr(TrimmedNonEmptyString),
  projectWorkspaceRoot: TrimmedNonEmptyString.annotate({
    description: "Root of the project's main workspace checkout."
  }),
  defaultStartFromOrigin: Schema65.Boolean.annotate({
    description: "Server default used by t3_worktree_handoff when startFromOrigin is omitted."
  })
});
var WorktreeMcpFailure = class extends Schema65.TaggedError()(
  "WorktreeMcpFailure",
  {
    code: Schema65.Literals([
      "capability_denied",
      "thread_not_found",
      "project_not_found",
      "already_in_worktree",
      "handoff_in_progress",
      "invalid_request",
      "operation_failed",
      "thread_credential_required"
    ]),
    message: Schema65.String
  }
) {
};

